import{BOARDING_RADIUS}from'../transport/boarding-approach.js';
import*as T from'three';
const coastControl=[[-14.9,-14],[-14.5,-18],[-10,-19.2],[-4,-18.6],[3,-19],[7.8,-18],[8,-12],[7.5,-4],[8.3,4],[7.8,13],[7.5,18],[1,19],[-7,18.6],[-12.6,19],[-15,15],[-14.4,7],[-15,-1],[-14.3,-9]],coastCurve=new T.CatmullRomCurve3(coastControl.map(([x,z])=>new T.Vector3(x,0,z)),true,'centripetal');
export const AIRPORT_SHORE=Object.freeze(Array.from({length:96},(_,i)=>{const p=coastCurve.getPoint(i/96);return Object.freeze([p.x,p.z]);}));
export const AIRPORT_BOUNDS=Object.freeze({minX:Math.min(...AIRPORT_SHORE.map(p=>p[0])),maxX:Math.max(...AIRPORT_SHORE.map(p=>p[0])),minZ:Math.min(...AIRPORT_SHORE.map(p=>p[1])),maxZ:Math.max(...AIRPORT_SHORE.map(p=>p[1]))});
export const AMUSEMENT_AIRPORT_FRAME=Object.freeze({x:28,y:-.0279,z:3,yaw:-Math.PI/2});
export function amusementAirportWorldPoint(p){const t=AMUSEMENT_AIRPORT_FRAME,c=Math.cos(t.yaw),s=Math.sin(t.yaw);return{...p,x:t.x+p.x*c+p.z*s,y:t.y+(p.y??.05),z:t.z-p.x*s+p.z*c,...(p.yaw===undefined?{}:{yaw:p.yaw+t.yaw})};}
export const AIRPORT_APPROACHES=Object.freeze([{parentRoomId:'courtyard',at:{x:16.6,z:-1.7},sign:{id:'village.airport.sign',x:16.6,z:-3.05,hx:.30,hz:.11},points:[[0,3.1],[0,-1.7],[7,-1.7],[10,-1.7],[16.6,-1.7]]},{parentRoomId:'amusementIsland',at:{x:13.5,z:-7.5},sign:{id:'amusement.airport.sign',x:13.5,z:-9.0,hx:.55,hz:.575,flat:true},points:[[0,7.1],[12.3,6.8],[12.75,6.35],[13.5,-7.5]]}]);
export const AIRPORT_ENDPOINTS=Object.freeze([{roomId:'villageAirport',parentRoomId:'courtyard',name:'별빛 마을 작은 공항',destination:'구름성 놀이섬',entry:{x:-10.5,y:.05,z:12.6,yaw:Math.PI},parentReturn:{x:16.6,z:-.3,yaw:-Math.PI/2},landing:{x:-10.5,y:.05,z:6,yaw:0},park:{x:-5,y:0,z:8,yaw:0},target:'amusementAirport'},{roomId:'amusementAirport',parentRoomId:'amusementIsland',name:'구름성 놀이섬 작은 공항',destination:'별빛 마을',entry:{x:-10.5,y:.05,z:12.6,yaw:Math.PI},parentReturn:amusementAirportWorldPoint({x:-10.5,z:14.5,yaw:Math.PI}),landing:{x:-10.5,y:.05,z:6,yaw:0},park:{x:-5,y:0,z:8,yaw:0},target:'villageAirport',targetAt:{x:-10.5,z:7.25}}]);
export const FLIGHT_ENDPOINTS=Object.freeze(Object.fromEntries(AIRPORT_ENDPOINTS.map(e=>[e.roomId,Object.freeze({...e,label:e.name,spawnId:'from-plane',destinationRoomId:e.target,target:Object.freeze({id:e.roomId+'.plane',type:'flight',at:e.targetAt??{x:-9.6,z:7.25},radius:BOARDING_RADIUS,requiresClearApproach:true,label:'비행기 타기 · '+e.destination})})])));
export function airportRoom(endpoint){if(!AIRPORT_ENDPOINTS.includes(endpoint))throw new RangeError('Unknown airport');return{id:endpoint.roomId,label:endpoint.name,endpoint,map:{label:endpoint.name,parent:endpoint.parentRoomId,x:50,y:57,caption:'작은 비행기로 '+endpoint.destination+'에 가요'},mapSpawnId:'entry',background:'#c4e2e6',bounds:AIRPORT_BOUNDS,shorePolygon:AIRPORT_SHORE,floorY:.05,spawns:{entry:{...endpoint.entry},'from-parent':{...endpoint.entry},'from-plane':{...endpoint.landing}},portals:[{id:endpoint.roomId+'.parent',type:'portal',at:{x:-10.5,z:14.5},radius:.7,label:endpoint.parentRoomId==='courtyard'?'별빛 마을로 돌아가기':'놀이섬으로 돌아가기',target:{roomId:endpoint.parentRoomId,spawnId:'from-airport'}}],routeLinks:[{via:'flight',target:{roomId:endpoint.target,spawnId:'from-plane'}}],obstacles:[{id:'airport.flight-field',x:-1.5,z:0,hx:7.3,hz:16},{id:'airport.windsock-pole',x:-11.85,z:8.3,hx:.045,hz:.045},...[-11.6,-9.4].flatMap(x=>[10,12.8].map(z=>({id:`airport.post.${x}.${z}`,x,z,hx:.07,hz:.07})))],interactables:[FLIGHT_ENDPOINTS[endpoint.roomId].target],collectibles:[],residents:[],camera:{position:[-15,8,20],target:[-9.2,.8,8],span:10,follow:true,followBounds:{minX:-13.8,maxX:-8.9,minZ:5,maxZ:15}}};}
export function flightRouteFrom(id){const from=FLIGHT_ENDPOINTS[id];return from?{id:from.roomId+'--'+from.destinationRoomId,from,to:FLIGHT_ENDPOINTS[from.destinationRoomId]}:null;}
